from aqrp.performance.metrics import fifo_statistics, summary


def book(cash=1000):
    s = initial_state(
        Q(cash),
        [
            {
                "security_id": "A",
                "lot": "1",
                "industry": "I",
                "beta": "1",
                "short_permission": True,
                "borrow_limit": "1000000000000000",
            }
        ],
    )
    s["assets"]["A"].update(mark=Q(100), tradable=True, in_universe=True)
    return s


def fill(s, n, p=100, f=1, session=0, name=None):
    return trade(
        s,
        fill_id=name or str(len(s["fills"])),
        sid="A",
        signed_qty=Q(n),
        p=Q(str(p)),
        fee=Q(str(f)),
        session=session,
        at="2024-02-01T09:00:00Z",
    )


def test_g01_g02_real_journal_known_answers():
    s = book()
    fill(s, 2)
    s["assets"]["A"]["mark"] = Q(105)
    record_valuation(s, "A", "mark105")
    assert (account(s)["cash_total"], account(s)["equity"]) == (Q(799), Q(1009))
    fill(s, -2, 105)
    assert account(s)["cash_total"] == Q(1008)
    assert account(s)["U_free"] == 210 and account(s)["cash_set"] == 798
    assert assert_economic_identity(s)["pnl"] == 8
    r = reconcile(Q(1000), s["journal"], ["A"])
    assert r["cash_total"] == 1008 and r["quantities"] == {"A": Q(0)}
    assert r["balances"]["positions_valuation"] == 0
    settle(s, 1, "settle")
    assert account(s)["cash_set"] == 1008


def test_average_cost_cross_zero_and_fee_once():
    s = book(10000)
    fill(s, 2, 100)
    fill(s, 3, 110)
    assert s["assets"]["A"]["cost"] == 106
    fill(s, -2, 120)
    assert s["realized_long"] == 28
    assert s["assets"]["A"]["quantity"] == 3
    fill(s, -5, 125)
    assert s["assets"]["A"]["quantity"] == -2
    assert s["assets"]["A"]["cost"] == 125
    assert s["fees"] == 4
    fill(s, 4, 110)
    assert s["assets"]["A"]["quantity"] == 2 and s["assets"]["A"]["cost"] == 110
    assert s["realized_short"] == 30
    assert_economic_identity(s)


def test_short_settlement_does_not_unfreeze_another_100():
    s = book()
    fill(s, -1)
    c = account(s)
    assert [
        c[k] for k in ("cash_total", "cash_set", "U_short", "S_set", "available", "equity")
    ] == [1099, 999, 100, 0, 899, 999]
    settle(s, 1, "settle")
    c = account(s)
    assert [c[k] for k in ("cash_set", "U_short", "S_set", "available")] == [1099, 0, 100, 899]
    fill(s, 1, 90, session=1)
    assert account(s)["cash_set"] == 1008 and account(s)["S_set"] == 0
    assert_economic_identity(s)


@pytest.mark.parametrize("settle_first", [False, True])
def test_partial_cover_cashlot_split_and_settlement(settle_first):
    s = book()
    fill(s, -2)
    s["assets"]["A"]["mark"] = Q(90)
    if settle_first:
        settle(s, 1, "before")
    fill(s, 1, 90)
    if not settle_first:
        assert [account(s)[k] for k in ("cash_set", "U_short", "U_free", "available")] == [
            908,
            100,
            100,
            818,
        ]
    settle(s, 1, "after")
    assert [account(s)[k] for k in ("cash_set", "S_set", "available", "equity")] == [
        1108,
        100,
        918,
        1018,
    ]
    assert_economic_identity(s)


def test_fifo_partial_closes_and_literal_ratio():
    s = book()
    fill(s, 2, name="entry")
    fill(s, -1, 104, name="exit1")
    fill(s, -1, 97, name="exit2")
    assert [f["net"] for f in s["fragments"]] == [Q(5, 2), Q(-9, 2)]
    m = fifo_statistics(s["fragments"])
    assert m["count"] == 2 and m["win_rate"]["value"] == Q(1, 2)
    assert m["profit_loss_ratio"]["value"] == Q(5, 9)
    assert sum(f["net"] for f in s["fragments"]) == -2


def test_historical_borrow_counterexample_and_partial_pools():
    s = book(10000)
    s["assets"]["A"]["mark"] = Q(1000)
    fill(s, -1, 1000, name="A")
    assert borrow(s, "day1", "A") == Q(4, 100)
    fill(s, -1, 1000, session=1, name="B")
    assert borrow(s, "day2", "A") == Q(8, 100)
    fill(s, 1, "997.93", session=2, name="closeA")
    assert s["fragments"][0]["net"] == Q(-1, 100)
    assert s["fragments"][0]["borrow"] == Q(8, 100)
    assert s["assets"]["A"]["lots"][1]["borrow"] == Q(4, 100)
    s2 = book(10000)
    s2["assets"]["A"]["mark"] = Q(1000)
    fill(s2, -2, 1000)
    borrow(s2, "b1", "A")
    fill(s2, 1, 1000)
    borrow(s2, "b2", "A")
    fill(s2, 1, 1000)
    assert [f["borrow"] for f in s2["fragments"]] == [Q(4, 100), Q(8, 100)]


@pytest.mark.parametrize("direction", [1, -1])
def test_split_dividend_pay_and_fifo_cost_conservation(direction):
    s = book()
    fill(s, direction * 2)
    initial = account(s)["equity"]
    split(s, "split", "A", Q(2))
    a = s["assets"]["A"]
    assert a["quantity"] == direction * 4 and a["cost"] == 50
    assert account(s)["equity"] == initial
    a["mark"] = Q(49)
    accrue(s, "div", "A", Q(direction * 4), kind="DIVIDEND_EX", pay_at="future")
    assert account(s)["equity"] == initial
    fill(s, -direction * 4, 49)
    assert s["fragments"][0]["net"] == -2
    closed = deepcopy(s["fragments"])
    pay(s, "div", "pay")
    assert s["fragments"] == closed and s["dividends"] == direction * 4
    assert_economic_identity(s)
    with pytest.raises(ContractError, match="DIVIDEND_RIGHT_NOT_FOUND"):
        pay(s, "missing", "event")


def test_exact_entry_exit_allocations_never_round_fragment_twice():
    s = book()
    fill(s, 3)
    for p in (101, 100, 99):
        fill(s, -1, p)
    assert [f["entry_fee"] for f in s["fragments"]] == [Q(1, 3)] * 3
    assert sum(f["entry_fee"] for f in s["fragments"]) == 1
    assert thaw(freeze(s)) == s
    assert present(Q(1, 3))["numerator"] == "1"
    assert present(Q(1, 8)) == "0.125"


