def test_invalid_ledger_branches_and_reconstruction_guards():
    s = book()
    fill(s, 1)
    assert sellable(s["assets"]["A"], 0) == 0 and sellable(s["assets"]["A"], 1) == 1
    with pytest.raises(ContractError, match="UNDEFINED_FRACTIONAL_SPLIT"):
        split(s, "x", "A", Q(1, 2))
    with pytest.raises(ContractError, match="UNBALANCED_FINANCIAL_JOURNAL"):
        _post(s, "bad", "bad", {"cash_set": Q(1)})
    bad = deepcopy(s["journal"])
    bad[0]["entries"][0]["amount"] += 1
    with pytest.raises(ContractError, match="RAW_JOURNAL_UNBALANCED"):
        reconcile(Q(1000), bad, ["A"])
    s["assets"]["A"]["lots"][0]["remaining"] += 1
    with pytest.raises(ContractError, match="LOT_QUANTITY_IDENTITY_FAILED"):
        assert_economic_identity(s)
    s["cash_set"] += 1
    with pytest.raises(ContractError, match="ECONOMIC_EQUITY_IDENTITY_FAILED"):
        assert_economic_identity(s)
    with pytest.raises(ContractError, match="INVALID_FILL_DOMAIN"):
        fill(book(), 0)


@pytest.mark.parametrize(
    "net,reason",
    [
        ([], "NO_CLOSED_FRAGMENTS"),
        ([0], "NO_NONZERO_OUTCOMES"),
        ([1], "NO_LOSERS"),
        ([-1], "NO_WINNERS"),
    ],
)
def test_fifo_undefined_and_zero(net, reason):
    result = fifo_statistics([{"net": Q(v)} for v in net])
    assert result["profit_loss_ratio"]["reason"] == reason


def test_g22_twr_sharpe_and_mdd():
    m = summary([Q(1, 10), Q(-1, 10), Q(1, 10)], [Q(1), Q(11, 10), Q(99, 100), Q(1089, 1000)])
    assert m["cumulative_return"]["value"] == Q(89, 1000)
    assert m["maximum_drawdown"]["value"] == Q(1, 10)
    assert m["sample_variance"]["value"] == Q(1, 75)
    assert m["sharpe"]["value"] == pytest.approx(4.582575694955840, abs=1e-12)
    assert summary([], [Q(1)])["cumulative_return"]["reason"] == "NO_SESSION_INTERVALS"
    assert summary([Q(0)], [Q(1), Q(1)])["sharpe"]["reason"] == "INSUFFICIENT_INTERVALS"
    assert summary([Q(0), Q(0)], [Q(1)] * 3)["sharpe"]["reason"] == "ZERO_VARIANCE"
    assert summary([Q(-1)], [Q(1), Q(0)])["cumulative_return"]["reason"] == "NONPOSITIVE_EQUITY"


@given(st.integers(1, 10**8), st.integers(1, 100000), st.integers(2, 40))
def test_fill_balance_split_and_decimal_context_property(qty, cents, precision):
    prior = getcontext().prec
    try:
        getcontext().prec = precision
        p = Q(cents, 100)
        s = book(10**20)
        fill(s, qty, p)
        before = account(s)["equity"]
        split(s, "split", "A", Q(2))
        assert account(s)["equity"] == before
        r = reconcile(s["initial_cash"], s["journal"], ["A"])
        assert r["cash_total"] == 10**20 - qty * p - 1
        assert r["quantities"]["A"] == qty * 2
        assert round_cent(Q(1005, 1000)) == Q(101, 100)
        assert ceil_tick(p) == floor_tick(p) == p
        assert_economic_identity(s)
    finally:
        getcontext().prec = prior


@pytest.mark.parametrize("side", ["BUY", "SELL"])
@pytest.mark.parametrize("kind", ["MARKET", "LIMIT"])
def test_fixed_price_domains_and_fee_upper(side, kind):
    low, high = bounds(Q(100), side, kind, Q(100) if kind == "LIMIT" else None)
    o = {"side": side, "low": low, "high": high}
    assert execute_price(o, Q("200400.41")) is None
    assert execute_price(o, Q(94)) is None
    assert fee_upper(Q(3), high) == 3


def test_g09_g12_ticks_and_minimum_commission():
    assert commission(Q(1), Q(100)) == 1
    assert commission(Q(15), Q("123.45")) == Q("1.85")
    assert execute_price({"side": "BUY", "low": Q(95), "high": Q(105)}, Q("100.03")) == Q("100.14")
    assert execute_price({"side": "SELL", "low": Q(95), "high": Q(105)}, Q("100.03")) == Q("99.92")
    with pytest.raises(ContractError):
        commission(Q(0), Q(100))


@pytest.mark.parametrize(
    "args",
    [
        (Q(100), "bad"),
        (Q(100), "BUY", "STOP"),
        (Q(100), "BUY", "MARKET", Q(100)),
        (Q(100), "BUY", "LIMIT", Q(90)),
        (Q(100), "SELL", "LIMIT", Q(110)),
        (Q(100), "BUY", "LIMIT", Q("100.001")),
    ],
)
def test_invalid_execution_configuration(args):
    with pytest.raises(ContractError):
        bounds(*args)


def test_capacity_lot_full_close_and_state_machine():
    o = {"remaining": Q(6), "signed_remaining": Q(6), "lot": Q(3)}
    assert fill_quantity(o, Q(10), Q(0)) == 6
    assert fill_quantity(o, Q(4), Q(0)) == 3
    assert fill_quantity(o, Q(0), Q(0)) == 0
    assert (
        fill_quantity({"remaining": Q(2), "signed_remaining": Q(-2), "lot": Q(3)}, Q(10), Q(2)) == 2
    )
    o = {"status": "CREATED", "history": []}
    transition(o, "SUBMITTED")
    transition(o, "ACCEPTED")
    transition(o, "PARTIALLY_FILLED")
    o.update(
        remaining=Q(2),
        signed_remaining=Q(2),
        reserve_notional=Q(200),
        cancelled_qty=Q(0),
        expired_remaining=Q(0),
    )
    cancel(o, "CANCELLED", "test")
    assert o["cancelled_qty"] == 2 and o["reserve_notional"] == 0
    with pytest.raises(ContractError, match="ILLEGAL_ORDER_TRANSITION"):
        transition(o, "FILLED")


def test_g24_large_exact_quantity_and_output_under_low_decimal_precision():
    prior = getcontext().prec
    try:
        getcontext().prec = 2
        s = book(10**35)
        s["assets"]["A"].update(mark=Q(1), lot=Q(3))
        fill(s, Q("99999999999999999999999999999999999"), 1, f=0)
        assert present(account(s)["cash_total"]) == "1"
        assert present(s["assets"]["A"]["quantity"]) == "99999999999999999999999999999999999"
        assert account(s)["equity"] == 10**35
    finally:
        getcontext().prec = prior


def test_g25_static_dual_budget_literal_answers():
    s = book()
    s["cash_set"] = Q(1150)
    s["cashlots"] = [
        {"amount": Q(50), "kind": "FREE", "settled": False},
        {"amount": Q(200), "kind": "SHORT", "settled": True},
    ]
    s["assets"]["A"].update(quantity=Q(-2), mark=Q(90))
    s["rights"] = {"R": {"amount": Q(4)}, "P": {"amount": Q(-2)}}
    s["budgets"] = {"static": {"total": Q(10), "paid": Q(0)}}
    s["current_budget"] = "static"
    c = account(s)
    assert [
        c[k]
        for k in (
            "cash_total",
            "equity",
            "cash_alloc",
            "equity_alloc",
            "P4_nonshort",
            "available",
            "P4_free",
            "H",
        )
    ] == [1200, 1022, 1138, 958, 20, 768, 758, 0]


def test_g21_flow_segment_twr_literal_twenty_one_percent():
    from aqrp.backtest.ledger import readonly_snapshot
    from aqrp.performance.metrics import performance

    s = book()
    fill(s, 10, 100, f=0)  # Isolated preapproved G21 arithmetic; not the per-Fill fee profile.
    s["valuations"] = [{"kind": "SESSION_CLOSE", **readonly_snapshot(s)}]
    s["assets"]["A"]["mark"] = Q(110)
    s["cash_set"] += 500
    s["external_flows"] = Q(500)
    _post(s, "external", "EXTERNAL_FLOW", {"cash_set": Q(500), "external_capital": Q(-500)})
    s["valuations"].append(
        {
            "kind": "EXTERNAL_FLOW",
            "before_equity": Q(1100),
            "amount": Q(500),
            **readonly_snapshot(s),
        }
    )
    s["assets"]["A"]["mark"] = Q(126)
    s["valuations"].append({"kind": "SESSION_CLOSE", **readonly_snapshot(s)})
    m = performance(s)
    assert m["cumulative_return"]["value"] == Q(21, 100)
    assert m["net_pnl"] == 260


@pytest.mark.parametrize("value", [Q(0), Q(-100), Q("0.01"), Q(10**35 - 10)])
def test_p4_input_is_exact_scientific_encoding(value):
    from aqrp.backtest.exact import p4_input
    from aqrp.portfolio.contracts import number

    assert number(p4_input(value)) == value


@pytest.mark.parametrize("value", [Q(1, 3), Q(10**35 - 1), Q(10**101)])
def test_p4_input_never_rounds_unrepresentable_projection(value):
    from aqrp.backtest.exact import p4_input

    with pytest.raises(ContractError, match="P4_PROJECTION_NUMERIC_DOMAIN_EXCEEDED"):
        p4_input(value)
